.page-center { display: flex; justify-content: center; align-items: center; height: 60vh; }

/* ── Grids ────────────────────────────────────────────────────────────────── */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
@media (max-width: 900px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .grid-2 { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .grid-4,.grid-3,.grid-2 { grid-template-columns: 1fr; }
}

/* ── Stat mini ────────────────────────────────────────────────────────────── */
.stat-mini  { padding: 16px 20px !important; }
.stat-label { font-size: 12px; color: var(--text-muted); font-weight: 500; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.05em; }
.stat-value { font-size: 22px; font-weight: 700; }

/* ── Spinner ──────────────────────────────────────────────────────────────── */
.spinner {
  width: 36px; height: 36px;
  border: 3px solid var(--border);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spinAnim 0.7s linear infinite;
}
.spin { display: inline-block; animation: spinAnim 1s linear infinite; }

/* ── Toolbar ──────────────────────────────────────────────────────────────── */
.toolbar      { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.search-wrap  { position: relative; flex: 1; min-width: 180px; }
.search-icon  { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: var(--text-muted); pointer-events: none; }
.search-input { padding-left: 32px !important; }

/* ── Table ────────────────────────────────────────────────────────────────── */
.table      { width: 100%; border-collapse: collapse; font-size: 14px; }
.table th   { padding: 10px 16px; text-align: left; font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); border-bottom: 1px solid var(--border); }
.table td   { padding: 12px 16px; border-bottom: 1px solid var(--border); vertical-align: middle; }
.table tr:last-child td { border-bottom: none; }
.table-row  { transition: background 0.15s; }
.table-row:hover { background: var(--bg-card-hover); }

/* ── Buttons ──────────────────────────────────────────────────────────────── */
.btn         { display: inline-flex; align-items: center; gap: 6px; padding: 8px 16px; border-radius: var(--radius-sm); border: none; cursor: pointer; font-family: inherit; font-size: 13px; font-weight: 600; transition: var(--transition); background: var(--primary); color: #fff; }
.btn:hover   { background: var(--primary-hover); transform: translateY(-1px); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }
.btn-ghost   { background: transparent; color: var(--text-muted); border: 1px solid var(--border); }
.btn-ghost:hover { background: var(--bg-card); color: var(--text); border-color: var(--border-hover); }
.btn-success { background: var(--green-dim); color: var(--green); border: 1px solid rgba(16,185,129,0.3); }
.btn-success:hover { background: rgba(16,185,129,0.25); transform: translateY(-1px); }
.btn-sm      { padding: 4px 10px; font-size: 11px; border-radius: 6px; }

/* ── Input ────────────────────────────────────────────────────────────────── */
.input        { width: 100%; padding: 9px 12px; border-radius: var(--radius-sm); border: 1px solid var(--border); background: rgba(255,255,255,0.04); color: var(--text); font-family: inherit; font-size: 13px; outline: none; transition: border-color 0.2s; }
.input:focus  { border-color: var(--primary); }
.input::placeholder { color: var(--text-muted); }
select.input  { appearance: none; cursor: pointer; }

/* ── Form grid ────────────────────────────────────────────────────────────── */
.form-grid      { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.form-label     { display: block; font-size: 12px; font-weight: 600; color: var(--text-muted); margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.05em; }
@media (max-width: 560px) { .form-grid { grid-template-columns: 1fr; } }

/* ── Modal ────────────────────────────────────────────────────────────────── */
.modal-overlay  { position: fixed; inset: 0; background: rgba(0,0,0,0.7); backdrop-filter: blur(4px); display: flex; align-items: center; justify-content: center; z-index: 1000; padding: 20px; animation: fadeIn 0.15s ease; }
.modal          { background: #13181f; border: 1px solid var(--border); border-radius: var(--radius-lg); width: 100%; max-width: 520px; max-height: 90vh; overflow-y: auto; animation: slideUp 0.2s ease; }
.modal__header  { display: flex; justify-content: space-between; align-items: center; padding: 20px 24px 16px; border-bottom: 1px solid var(--border); }
.modal__title   { font-size: 17px; font-weight: 700; }
.modal__body    { padding: 20px 24px 24px; }

/* ── Tabs ─────────────────────────────────────────────────────────────────── */
.tabs           { display: flex; gap: 4px; border-bottom: 1px solid var(--border); }
.tab-btn        { padding: 8px 16px; background: none; border: none; border-bottom: 2px solid transparent; cursor: pointer; font-family: inherit; font-size: 13px; font-weight: 500; color: var(--text-muted); transition: color 0.2s, border-color 0.2s; margin-bottom: -1px; }
.tab-btn:hover  { color: var(--text); }
.tab-btn--active { color: var(--primary); border-bottom-color: var(--primary); }

/* ── Card ─────────────────────────────────────────────────────────────────── */
.card        { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px 24px; transition: var(--transition); }
.card:hover  { border-color: var(--border-hover); }

/* ── Helpers ──────────────────────────────────────────────────────────────── */
.text-muted  { color: var(--text-muted); }
.text-sm     { font-size: 12px; }

/* ── Sidebar (if not already defined) ────────────────────────────────────── */
.sidebar          { width: 220px; min-height: 100vh; background: var(--bg-sidebar); border-right: 1px solid var(--border); display: flex; flex-direction: column; padding: 20px 12px; flex-shrink: 0; }
.sidebar__logo    { display: flex; align-items: center; gap: 10px; padding: 0 8px 20px; border-bottom: 1px solid var(--border); margin-bottom: 16px; }
.sidebar__logo-icon { color: var(--primary); }
.sidebar__title   { font-weight: 700; font-size: 15px; }
.sidebar__sub     { font-size: 11px; color: var(--text-muted); }
.sidebar__nav     { display: flex; flex-direction: column; gap: 4px; flex: 1; }
.sidebar__link    { display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: var(--radius-sm); font-size: 13px; font-weight: 500; color: var(--text-muted); text-decoration: none; transition: var(--transition); }
.sidebar__link:hover { background: var(--bg-card); color: var(--text); }
.sidebar__link--active { background: var(--primary-dim); color: var(--primary); }
.sidebar__footer  { display: flex; align-items: center; gap: 8px; padding: 12px 8px 0; border-top: 1px solid var(--border); }
.main             { flex: 1; overflow-y: auto; }
.app              { display: flex; min-height: 100vh; }

/* ── Status dots ──────────────────────────────────────────────────────────── */
