/* ── Tabs ─────────────────────────────────────────────────────────────────── */
.tabs           { display: flex; gap: 4px; border-bottom: 1px solid var(--border); }
.tab-btn        { padding: 8px 16px; background: none; border: none; border-bottom: 2px solid transparent; cursor: pointer; font-family: inherit; font-size: 13px; font-weight: 500; color: var(--text-muted); transition: color 0.2s, border-color 0.2s; margin-bottom: -1px; }
.tab-btn:hover  { color: var(--text); }
.tab-btn--active { color: var(--primary); border-bottom-color: var(--primary); }

/* ── Card ─────────────────────────────────────────────────────────────────── */
.card        { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px 24px; transition: var(--transition); }
.card:hover  { border-color: var(--border-hover); }

/* ── Helpers ──────────────────────────────────────────────────────────────── */
.text-muted  { color: var(--text-muted); }
.text-sm     { font-size: 12px; }

/* ── Sidebar (if not already defined) ────────────────────────────────────── */
.sidebar          { width: 220px; min-height: 100vh; background: var(--bg-sidebar); border-right: 1px solid var(--border); display: flex; flex-direction: column; padding: 20px 12px; flex-shrink: 0; }
.sidebar__logo    { display: flex; align-items: center; gap: 10px; padding: 0 8px 20px; border-bottom: 1px solid var(--border); margin-bottom: 16px; }
.sidebar__logo-icon { color: var(--primary); }
.sidebar__title   { font-weight: 700; font-size: 15px; }
.sidebar__sub     { font-size: 11px; color: var(--text-muted); }
.sidebar__nav     { display: flex; flex-direction: column; gap: 4px; flex: 1; }
.sidebar__link    { display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: var(--radius-sm); font-size: 13px; font-weight: 500; color: var(--text-muted); text-decoration: none; transition: var(--transition); }
.sidebar__link:hover { background: var(--bg-card); color: var(--text); }
.sidebar__link--active { background: var(--primary-dim); color: var(--primary); }
.sidebar__footer  { display: flex; align-items: center; gap: 8px; padding: 12px 8px 0; border-top: 1px solid var(--border); }
.main             { flex: 1; overflow-y: auto; }
.app              { display: flex; min-height: 100vh; }

/* ── Status dots ──────────────────────────────────────────────────────────── */
.status-dot         { display: inline-block; width: 8px; height: 8px; border-radius: 50%; }
.status-dot--alert-ok { background: var(--green); animation: pulse 2s infinite; }

/* ═══════════════════════════════════════════════════════════════════════════
   Smart Import Page
   ═══════════════════════════════════════════════════════════════════════════ */

.import-page { max-width: 960px; }
.import-header { margin-bottom: 24px; }
.import-page-title { font-size: 22px; font-weight: 700; margin-bottom: 4px; }

/* ── Stepper ─────────────────────────────────────────────────────────────── */
.import-stepper {
  display: flex;
  align-items: center;
  gap: 0;
  margin-bottom: 32px;
}
.import-stepper__item {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 500;
}
.import-stepper__item.active  { color: var(--primary); }
.import-stepper__item.done    { color: var(--green); }
.import-stepper__dot {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-card);
  border: 1.5px solid var(--border);
  font-size: 12px;
  font-weight: 700;
  flex-shrink: 0;
  transition: var(--transition);
}
.import-stepper__item.active .import-stepper__dot  { border-color: var(--primary); color: var(--primary); background: var(--primary-dim); }
.import-stepper__item.done .import-stepper__dot    { border-color: var(--green);   color: var(--green);   background: rgba(16,185,129,.12); }
.import-stepper__label { white-space: nowrap; }
.import-stepper__line  { height: 1.5px; width: 40px; background: var(--border); margin: 0 8px; flex-shrink: 0; }

/* ── Step container ───────────────────────────────────────────────────────── */
.import-step { display: flex; flex-direction: column; gap: 20px; }
.import-step__title { font-size: 18px; font-weight: 700; }
.import-step__desc  { font-size: 14px; }
.import-step__actions { display: flex; gap: 12px; align-items: center; }

/* ── Type cards ───────────────────────────────────────────────────────────── */
.import-types-row { display: flex; gap: 12px; }
.import-type-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 16px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}
.import-type-card__label { font-size: 13px; font-weight: 600; }
.import-type-card__ext   { font-size: 11px; }

/* ── Drop zone ────────────────────────────────────────────────────────────── */
.import-dropzone {
  border: 2px dashed var(--border);
  border-radius: var(--radius);
  padding: 48px 32px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  transition: var(--transition);
  background: var(--bg-card);
}
.import-dropzone:hover, .import-dropzone--active {
  border-color: var(--primary);
  background: var(--primary-dim);
}
.import-dropzone__icon { color: var(--primary); opacity: .7; }
.import-dropzone__text { font-size: 15px; font-weight: 500; }
.link-text { color: var(--primary); text-decoration: underline; }

/* ── File chips ───────────────────────────────────────────────────────────── */
.import-file-list { display: flex; flex-wrap: wrap; gap: 8px; }
.import-file-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 20px;
  font-size: 12px;
  max-width: 260px;
  overflow: hidden;
}
.import-file-chip span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.import-file-chip__remove {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  padding: 0;
  flex-shrink: 0;
}
.import-file-chip__remove:hover { color: var(--red); }

/* ── Analyse button ───────────────────────────────────────────────────────── */
.import-analyse-btn { align-self: flex-start; gap: 8px; display: flex; align-items: center; }

/* ── Preview table ────────────────────────────────────────────────────────── */
.import-table-wrap { overflow-x: auto; border-radius: var(--radius); border: 1px solid var(--border); }
.import-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.import-table th {
  background: var(--bg-card);
  padding: 10px 12px;
  text-align: left;
  font-weight: 600;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}
.import-table td {
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}
.import-row:last-child td { border-bottom: none; }
.import-row:hover td { background: var(--bg-card); }
.import-row--error td { background: rgba(239,68,68,.06); }

.import-cell-input, .import-cell-select {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 4px 8px;
  font-size: 12px;
  color: var(--text);
  width: 100%;
  min-width: 80px;
}
.import-cell-input:focus, .import-cell-select:focus {
  outline: none;
  border-color: var(--primary);
}

.import-src-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-muted);
  text-transform: capitalize;
}
.import-conf-badge { font-size: 12px; font-weight: 600; }
.import-del-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-muted);
  padding: 4px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
}
.import-del-btn:hover { color: var(--red); background: rgba(239,68,68,.1); }
.import-empty { padding: 32px; text-align: center; color: var(--text-muted); font-size: 13px; }

/* ── Error banner ─────────────────────────────────────────────────────────── */
.import-error-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background: rgba(239,68,68,.1);
  border: 1px solid rgba(239,68,68,.3);
  border-radius: var(--radius);
  color: var(--red);
  font-size: 13px;
}

/* ── Done step ────────────────────────────────────────────────────────────── */
.import-step--done {
  align-items: center;
  text-align: center;
  padding: 40px 0;
}
.import-done-icon { color: var(--green); margin-bottom: 8px; }
.import-done-counts {
  display: flex;
  gap: 40px;
  margin: 24px 0;
}
.import-done-stat { display: flex; flex-direction: column; align-items: center; gap: 4px; }
.import-done-stat__num { font-size: 36px; font-weight: 800; color: var(--text); }
.import-done-actions { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }

/* ── Spin animation ───────────────────────────────────────────────────────── */
@keyframes spin { to { transform: rotate(360deg); } }
.spin { animation: spin 1s linear infinite; }
